VALUES ('7eed0709-9855-5061-a364-f6ae8e24d22e', '4c8f0f9e-b436-5cb7-bca9-7dae53a743dd', 'd4e5d988-62c6-54ad-bdb8-9ba39b1e5710', 'Party Relationship', 'Shows one Party Relationship at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 3 fields marked with a red asterisk (*) must have a value before Save will accept the record. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
