-- --------------------------------------------------------------------------
-- Address (bus_address)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('84225c36-03d3-577b-8b69-f978c61fb956', 'Address', 'Maintain Address records', 'Create, find and maintain Address records. The list shows every Address you have access to — select a row to open it, or use New to add one. Each row is a single Address, described by 18 fields.

Id is unique: no two Address records may share the same value, and a save that would duplicate one is rejected. Address Type, Line1, City, Country Code, Is Primary and Status must be filled in before the record can be saved.

Every Address points at Party, Person, Organization, Customer and Supplier. Choose the linked record from the lookup on those fields rather than typing an identifier. Location refers back to Address, so what you change here can affect that record.

Every save starts as a Draft. The business rules and workflows attached to Address then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. An Address with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('78e6ff16-ccdb-5174-915b-5074a7ef5c00', 'bus_address', 'Address', 'Reusable address master data with explicit rules for ownership, primary selection, lifecycle, and historical transaction evidence. Address is reusable master data, but an address printed on an issued invoice, shipment, order, or other historical document is transaction evidence and must remain reproducible even if the master address changes. Supports Party, Organization, Customer, Supplier, Location, order, fulfillment, invoicing, taxation, shipping, reporting, and integration workflows. Party and Location may reuse an Address. Operational documents should resolve the effective address at transaction time and preserve the result where historical reproduction is required. Address create/update → validate country/geography → validate Party/Location dependency → select effective address → transaction captures address evidence → later master-data changes affect future selection only. Active → inactive/retired. Retirement prevents new normal use but does not remove historical references or snapshots. A Customer changes its billing address. The Customer master now points to the new active address, while already issued Invoices retain the address effective when they were issued.', 'A', FALSE, FALSE, FALSE, TRUE, '84225c36-03d3-577b-8b69-f978c61fb956', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
