VALUES ('a3cee190-de3b-576d-90de-ddc3763e190e', '3809ee4f-1708-501c-9a42-e116c5dd06f5', '8be56349-9b92-56cf-9379-532b099ad4aa', '0b0c39c8-2eea-545a-b2a9-d9593d5a7b5a', 'Id', 'Stable identity of the unit-of-measure definition. Referenced by Product, transaction lines, inventory, and conversion rules. Identifies the measurement definition rather than a quantity value. Allows every quantity-bearing workflow to resolve exactly how a numeric quantity must be interpreted. Required for unambiguous measurement semantics. Must be unique: a save is rejected if another Unit Of Measure already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
