INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('1e3ff883-e82e-55a4-8c6b-ccd36ef476e0', '3809ee4f-1708-501c-9a42-e116c5dd06f5', '3f0981c7-7a9b-57e1-87a9-feec116b191a', '0b0c39c8-2eea-545a-b2a9-d9593d5a7b5a', 'Code', 'Standard business code for the unit, such as EACH, KG, L, HOUR, or DAY. Used in forms, integrations, documents, validation, and quantity display. Code identifies the unit definition; it does not represent a conversion or quantity itself. Used to resolve units during order entry, purchasing, receipt, inventory, invoicing, and reporting. Required for operational interoperability. Required — the record cannot be saved while this is empty. Must be unique: a save is rejected if another Unit Of Measure already uses this value. Up to 30 characters.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
