VALUES ('8575a553-ee45-54e4-b087-baec7267b8c8', 'a38d870e-4bd8-5d38-95a4-7cb10174301b', 'aff85104-1552-55a1-9b90-b5f647685bc8', 'Calendar', 'Shows one Calendar at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 2 fields marked with a red asterisk (*) must have a value before Save will accept the record. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
