VALUES ('18be4623-1692-540a-a834-b065f92d08b4', '60035f5d-945c-5ca6-ad43-8ecf97f09274', 'credit_limit', 'Credit Limit', 'Authorized monetary credit exposure limit. Used in credit checks exposure monitoring and risk reporting. Must be interpreted with currency outstanding exposure payment terms and credit status. Provides one input to credit authorization before additional exposure. Optional for cash-only customers.', 12, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
