VALUES ('665f9bd6-f59b-52ea-91ad-1f7c63b379f5', '35b9b587-f54a-5df2-95a5-9a7b7f86d872', 'source', 'Source', 'Captures the business meaning of source for the Lead. It is interpreted together with the entity''s other attributes and relationships to support the processes that manage this record. Used when creating, reviewing, searching, validating, reporting on, or integrating Lead records, where applicable. Its meaning is specific to Lead; it must be interpreted with the entity''s relationships, lifecycle, and business rules rather than as an isolated technical value. Optional because the business concept can remain valid when this value is not yet known or is not applicable.', 10, 100, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
