INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('1e379cd8-31ed-5fc5-bd01-d121b137297e', 'Opportunity', 'Maintain Opportunity records', 'Create, find and maintain Opportunity records. The list shows every Opportunity you have access to — select a row to open it, or use New to add one. Each row is a single Opportunity, described by 10 fields.

Id and Opportunity Number are unique: no two Opportunity records may share the same value, and a save that would duplicate one is rejected. Opportunity Number, Name and Stage must be filled in before the record can be saved.

Every Opportunity points at Customer and Sales Order. Choose the linked record from the lookup on those fields rather than typing an identifier. Lead and Quotation refer back to Opportunity, so what you change here can affect those records.

Every save starts as a Draft. The business rules and workflows attached to Opportunity then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. An Opportunity with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('07edc4e9-e269-5a1b-a64d-0035d86f3621', 'bus_opportunity', 'Opportunity', 'Represents a crm entity called Opportunity within the CEDM business model. Opportunity is a business concept with its own identity and lifecycle. It captures information that must remain understandable independently of a database, API, or user interface. Used by business processes, transactions, forms, reports, integrations, and domain capabilities that create, find, change, or relate Opportunity records. The entity participates in a wider business graph through relationships with Customer, Party, Lead, SalesOrder. These relationships provide the context needed to interpret the record rather than treating its fields as isolated database columns. The entity lifecycle is governed by its status, invariants, and related business processes. State changes must preserve the declared business meaning and relationships. A typical Opportunity record represents one identifiable business occurrence or master-data object that can be referenced by related CEDM processes.', 'A', FALSE, FALSE, FALSE, TRUE, '1e379cd8-31ed-5fc5-bd01-d121b137297e', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9928b248-c98e-5380-9ac7-db54a9a9f1f8', '1e379cd8-31ed-5fc5-bd01-d121b137297e', '07edc4e9-e269-5a1b-a64d-0035d86f3621', 'Opportunity', 'Shows one Opportunity at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 3 fields marked with a red asterisk (*) must have a value before Save will accept the record. Customer and Sales Order are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e9deaae1-46d5-59b6-b987-9efc9f544b26', '07edc4e9-e269-5a1b-a64d-0035d86f3621', 'id', 'Id', 'Identifies the opportunity record associated with this Opportunity. The identifier connects this record to the corresponding CEDM entity so related processes can resolve the correct business object. Used when creating, reviewing, searching, validating, reporting on, or integrating Opportunity records, where applicable. Its meaning is specific to Opportunity; it must be interpreted with the entity''s relationships, lifecycle, and business rules rather than as an isolated technical value. Required because the business model cannot reliably interpret the record for its declared purpose without this value.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
