INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('be0b3b38-2cf4-5cb9-b4da-8507f69b0c6b', 'Quotation', 'Maintain Quotation records', 'Create, find and maintain Quotation records. The list shows every Quotation you have access to — select a row to open it, or use New to add one. Each row is a single Quotation, described by 10 fields.

Id and Quotation Number are unique: no two Quotation records may share the same value, and a save that would duplicate one is rejected. Quotation Number, Quotation Date, Status, Currency, Total Amount and Customer must be filled in before the record can be saved.

Every Quotation points at Currency, Customer and Opportunity. Choose the linked record from the lookup on those fields rather than typing an identifier. Quotation Line refers back to Quotation, so what you change here can affect that record.

Every save starts as a Draft. The business rules and workflows attached to Quotation then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Quotation with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('f6edc017-13d0-55fd-97e9-9ed8746e48ea', 'bus_quotation', 'Quotation', 'Represents a commercial transaction called Quotation within the CEDM business model. Quotation is a business concept with its own identity and lifecycle. It captures information that must remain understandable independently of a database, API, or user interface. Used by business processes, transactions, forms, reports, integrations, and domain capabilities that create, find, change, or relate Quotation records. The entity participates in a wider business graph through relationships with Customer, Opportunity, QuotationLine, PaymentTerm. These relationships provide the context needed to interpret the record rather than treating its fields as isolated database columns. The entity lifecycle is governed by its status, invariants, and related business processes. State changes must preserve the declared business meaning and relationships. A typical Quotation record represents one identifiable business occurrence or master-data object that can be referenced by related CEDM processes.', 'A', FALSE, FALSE, FALSE, TRUE, 'be0b3b38-2cf4-5cb9-b4da-8507f69b0c6b', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('5d3e1336-2314-543f-bc98-8abec54be8e7', 'be0b3b38-2cf4-5cb9-b4da-8507f69b0c6b', 'f6edc017-13d0-55fd-97e9-9ed8746e48ea', 'Quotation', 'Shows one Quotation at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 6 fields marked with a red asterisk (*) must have a value before Save will accept the record. Currency, Customer and Opportunity are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
