VALUES ('2fb3176e-2bd1-53d6-9259-bd279f1ecb24', 'f6edc017-13d0-55fd-97e9-9ed8746e48ea', 'id', 'Id', 'Identifies the quotation record associated with this Quotation. The identifier connects this record to the corresponding CEDM entity so related processes can resolve the correct business object. Used when creating, reviewing, searching, validating, reporting on, or integrating Quotation records, where applicable. Its meaning is specific to Quotation; it must be interpreted with the entity''s relationships, lifecycle, and business rules rather than as an isolated technical value. Required because the business model cannot reliably interpret the record for its declared purpose without this value.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
