VALUES ('7b30adbd-cff7-5983-830a-c3ea1c847c5a', '7de69a61-f853-5855-afdd-2c129a6d293c', 'ef1d214f-8172-5494-b63d-a211884ae058', '0b0c39c8-2eea-545a-b2a9-d9593d5a7b5a', 'Id', 'Immutable Supplier role identity. Connects procurement purchase orders receipts invoices payments returns credits claims resolutions and supplier performance. Supplier identifies the role while PartyRole and Party identify the underlying party. Preserves supplier traceability across procure-to-pay reverse procurement claim recovery and performance management. Required for stable supplier history. Must be unique: a save is rejected if another Supplier already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
