INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('eaf2a8b8-60c1-5c96-9246-42f54b6ffa25', '7de69a61-f853-5855-afdd-2c129a6d293c', 'cbf1a6cb-bf60-5c12-bf19-7d3d8fb4b60d', '0b0c39c8-2eea-545a-b2a9-d9593d5a7b5a', 'Party Role', 'PartyRole backing the Supplier specialization. Navigates to common party identity and role information. Supplier must not duplicate Party identity. Supplies shared party context to procurement and financial workflows. Required for role specialization. Required — the record cannot be saved while this is empty. Must be unique: a save is rejected if another Supplier already uses this value.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('da216388-7f0a-5039-8f7a-b0028d629a5b', '7de69a61-f853-5855-afdd-2c129a6d293c', 'efdfa73d-1f25-55fa-a7d9-9c8099764257', '0b0c39c8-2eea-545a-b2a9-d9593d5a7b5a', 'Supplier Code', 'Enterprise supplier business reference. Used on purchase orders receipts invoices returns credits payments claims portals reports and integrations. Distinct from legal name and external registration identifiers. Identifies the supplier across procurement settlement recovery and performance. Required for operational recognition. Required — the record cannot be saved while this is empty. Must be unique: a save is rejected if another Supplier already uses this value. Up to 100 characters.', 30, 30, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
