VALUES ('9bc46fa4-46cf-58a9-8217-837a4bf010c7', '7de69a61-f853-5855-afdd-2c129a6d293c', '9b640ac5-60cb-5f16-8238-8486b39c79ec', 'ae488805-a94b-563a-a32d-bcadd652e9ac', 'Role Type', 'Defines the business capacity in which the Party participates. Determines specialized capabilities, policies, workflows, and validations. Separate from Party.partyType, which describes whether the participant is a person or organization. Selects the applicable downstream role specialization and business process. Required for contextual participation. Required — the record cannot be saved while this is empty.', 90, 90, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
