-- --------------------------------------------------------------------------
-- Payment Term (bus_payment_term)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('faf65c47-6ec1-5062-a19e-d82d2b645008', 'Payment Term', 'Maintain Payment Term records', 'Create, find and maintain Payment Term records. The list shows every Payment Term you have access to — select a row to open it, or use New to add one. Each row is a single Payment Term, described by 10 fields.

Id and Code are unique: no two Payment Term records may share the same value, and a save that would duplicate one is rejected. Code, Name, Due Days, Due Date Basis and Status must be filled in before the record can be saved.

Sales Order and Purchase Order refer back to Payment Term, so what you change here can affect those records.

Every save starts as a Draft. The business rules and workflows attached to Payment Term then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Payment Term with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('fc2a2c98-d0a4-510b-bd24-5097e20dbe9b', 'bus_payment_term', 'Payment Term', 'Defines reusable commercial rules for when financial obligations become due and when early-settlement benefits or operational grace periods apply. PaymentTerm is a policy definition; an actual Invoice due date is a transaction-level result calculated from that policy and the applicable business event. Central to customer credit, supplier procurement, SalesOrder, PurchaseOrder, Invoice, receivables, payables, collections, cash forecasting, and payment scheduling. Customer and Supplier provide default role-level terms. SalesOrder and PurchaseOrder provide transaction context. Invoice derives an actual due date. Payment settles the obligation; PaymentTerm does not itself represent a Payment. Customer/Supplier default → SalesOrder/PurchaseOrder selection → Invoice creation → due-date calculation → receivable/payable aging → Payment scheduling → settlement. A term may be overridden by an authorized contract or transaction-level agreement, but the effective term used for an issued financial document must remain auditable. Payment terms can be created, activated, made inactive, and retired. Master-data changes affect future selection; issued transaction terms and calculated due dates remain historically stable unless formally amended. NET30 with INVOICE_DATE and dueDays 30 means an invoice issued on 10 August has a nominal due date of 9 September. If the term also specifies 2% within 10 days, the early-payment window is separately evaluated; the PaymentTerm does not itself create or allocate a payment.', 'A', FALSE, FALSE, FALSE, TRUE, 'faf65c47-6ec1-5062-a19e-d82d2b645008', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e86da093-64fd-59a4-b5ed-c439a6f706d3', 'faf65c47-6ec1-5062-a19e-d82d2b645008', 'fc2a2c98-d0a4-510b-bd24-5097e20dbe9b', 'Payment Term', 'Shows one Payment Term at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 5 fields marked with a red asterisk (*) must have a value before Save will accept the record. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('deb79052-3dcc-5e59-86b6-14a3cad367b5', 'fc2a2c98-d0a4-510b-bd24-5097e20dbe9b', 'id', 'Id', 'Stable identity of the payment-term policy. Referenced by Customer, Supplier, SalesOrder, PurchaseOrder, Invoice, and applicable contracts. Identifies the policy definition, not a particular invoice due date or payment event. Provides reusable settlement timing rules that are copied or resolved into transaction-level due-date calculations. Required for traceable commercial terms.', 13, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, TRUE, FALSE, 10, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4705b606-19a1-5a6d-91c4-2800fa2429aa', 'fc2a2c98-d0a4-510b-bd24-5097e20dbe9b', 'code', 'Code', 'Business code for the payment-term policy, such as NET30 or DUE_ON_RECEIPT. Used in customer/supplier master data, order entry, procurement, invoices, reports, and integrations. Code identifies the reusable policy; it is not itself a due date. Provides a selectable default during commercial transaction creation. Required for operational identification.', 10, 50, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('fa638b1a-fc80-5bb7-8fb8-5f8c5796732b', 'fc2a2c98-d0a4-510b-bd24-5097e20dbe9b', 'name', 'Name', 'Human-readable name of the settlement-timing policy. Used in configuration, forms, documents, reporting, and user selection. Describes the policy represented by code and paymentTermId. Makes commercial settlement conditions understandable during order, procurement, and billing processes. Required for usable master data.', 10, 150, NULL, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('3190b279-b9fe-55e2-a71e-9da124ea48ca', 'fc2a2c98-d0a4-510b-bd24-5097e20dbe9b', 'due_days', 'Due Days', 'Number of calendar days normally added to the applicable due-date base event to calculate contractual payment due date. Used by Invoice and receivables/payables processes to calculate expected settlement dates. Must be interpreted with dueDateBasis; it is not necessarily calculated from order date. Converts a transaction''s defined due-date basis into a scheduled due date. Required for terms based on a day offset, including zero days.', 11, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('2b8c547c-c606-51bb-b6a1-9c104835c9cd', 'fc2a2c98-d0a4-510b-bd24-5097e20dbe9b', 'due_date_basis', 'Due Date Basis', 'Defines the business event from which dueDays is calculated. Used by invoicing, accounts receivable, accounts payable, collections, and cash-flow forecasting. The basis event comes from the applicable transaction workflow and may differ between sales and procurement contexts. Determines how the Invoice due date or payable obligation date is derived. Due date is calculated from the invoice issue/accounting date according to policy. Due date is calculated from the applicable delivery event. Due date is calculated from accepted receipt evidence, typically in procurement. Due date is calculated according to month-end terms and the configured day-offset interpretation. A transaction or agreement-specific rule supplies the due-date basis and calculation. Required because dueDays has no complete business meaning without a basis.', 1025, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('069b91b7-8955-5218-80ed-aff18f87e6fb', 'fc2a2c98-d0a4-510b-bd24-5097e20dbe9b', 'discount_days', 'Discount Days', 'Number of days during which an early-payment discount may be available. Used by receivables, payables, payment scheduling, cash forecasting, and discount calculation. Applies only when an early-payment discount rate or amount is also defined. Establishes the time window for discounted settlement. Optional when no early-payment discount is offered.', 11, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e51c6a54-9612-5b35-b184-e3f3035fffe2', 'fc2a2c98-d0a4-510b-bd24-5097e20dbe9b', 'discount_percent', 'Discount Percent', 'Percentage reduction available when the applicable obligation is settled within the discount window. Used for payment planning, invoice presentation, cash forecasting, and settlement calculation. Must be interpreted together with discountDays and the applicable transaction amount. Allows Payment scheduling and Invoice terms to determine whether early settlement qualifies for discount. Optional when no percentage discount applies.', 12, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e85d7278-0024-5d87-8cf9-a8c62c93a768', 'fc2a2c98-d0a4-510b-bd24-5097e20dbe9b', 'grace_days', 'Grace Days', 'Additional days allowed after the nominal due date before a policy considers the obligation overdue for a defined process. Used by collections, credit control, late-payment reporting, and supplier payment management. Grace period does not necessarily change the contractual due date; it changes the operational escalation threshold. Separates contractual due date from collection or escalation timing. Optional when no grace period applies.', 11, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 80, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d4c05790-3415-5d71-b22d-e7ea9cf4a11d', 'fc2a2c98-d0a4-510b-bd24-5097e20dbe9b', 'description', 'Description', 'Human-readable explanation of the payment policy and its operational interpretation. Used in configuration, audit, transaction review, and user guidance. Supplements structured rules and must not be the sole source for due-date calculation. Optional where structured attributes fully describe the policy.', 10, 1000, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 90, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('43ff0dba-8ce3-585c-a579-ff3e58b9127e', 'fc2a2c98-d0a4-510b-bd24-5097e20dbe9b', 'status', 'Status', 'Controls whether the payment-term policy can be selected for new transactions. Used by customer/supplier maintenance, order capture, procurement, invoicing, and contracts. Retiring a term must not change historical transaction due dates that were calculated from it. New transactions normally select ACTIVE terms; historical transactions preserve their effective terms and derived dates. Available for normal new transaction use. Temporarily unavailable for new selection. No longer available for new selection while historical references remain valid. Required for master-data eligibility.', 1026, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 100, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e0abbd15-dbb0-54ae-9c9e-f25cc18b861a', 'e86da093-64fd-59a4-b5ed-c439a6f706d3', 'deb79052-3dcc-5e59-86b6-14a3cad367b5', '0b0c39c8-2eea-545a-b2a9-d9593d5a7b5a', 'Id', 'Stable identity of the payment-term policy. Referenced by Customer, Supplier, SalesOrder, PurchaseOrder, Invoice, and applicable contracts. Identifies the policy definition, not a particular invoice due date or payment event. Provides reusable settlement timing rules that are copied or resolved into transaction-level due-date calculations. Required for traceable commercial terms. Must be unique: a save is rejected if another Payment Term already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('696a974c-e438-5e2a-b126-5ed66cd638c8', 'e86da093-64fd-59a4-b5ed-c439a6f706d3', '4705b606-19a1-5a6d-91c4-2800fa2429aa', '0b0c39c8-2eea-545a-b2a9-d9593d5a7b5a', 'Code', 'Business code for the payment-term policy, such as NET30 or DUE_ON_RECEIPT. Used in customer/supplier master data, order entry, procurement, invoices, reports, and integrations. Code identifies the reusable policy; it is not itself a due date. Provides a selectable default during commercial transaction creation. Required for operational identification. Required — the record cannot be saved while this is empty. Must be unique: a save is rejected if another Payment Term already uses this value. Up to 50 characters.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('babf5f34-2c16-5076-96da-6acaf4b1e2c5', 'e86da093-64fd-59a4-b5ed-c439a6f706d3', 'fa638b1a-fc80-5bb7-8fb8-5f8c5796732b', '0b0c39c8-2eea-545a-b2a9-d9593d5a7b5a', 'Name', 'Human-readable name of the settlement-timing policy. Used in configuration, forms, documents, reporting, and user selection. Describes the policy represented by code and paymentTermId. Makes commercial settlement conditions understandable during order, procurement, and billing processes. Required for usable master data. Required — the record cannot be saved while this is empty. Up to 150 characters.', 30, 30, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4d748ff9-2834-523f-b765-930ab7f315df', 'e86da093-64fd-59a4-b5ed-c439a6f706d3', '3190b279-b9fe-55e2-a71e-9da124ea48ca', 'ae488805-a94b-563a-a32d-bcadd652e9ac', 'Due Days', 'Number of calendar days normally added to the applicable due-date base event to calculate contractual payment due date. Used by Invoice and receivables/payables processes to calculate expected settlement dates. Must be interpreted with dueDateBasis; it is not necessarily calculated from order date. Converts a transaction''s defined due-date basis into a scheduled due date. Required for terms based on a day offset, including zero days. Required — the record cannot be saved while this is empty.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
