VALUES ('bd1be46c-9c0d-5940-ab97-927da0338064', 'deffc47d-af26-54d0-91ff-b41e9dbad546', '9b6e2ff4-1d54-5596-a4ea-43e6c556286c', 'Pricing', 'Shows one Pricing at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
