INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('72f2359d-70d2-5bc0-a91a-7609935a3571', 'Prospect', 'Maintain Prospect records', 'Create, find and maintain Prospect records. The list shows every Prospect you have access to — select a row to open it, or use New to add one. Each row is a single Prospect, described by 3 fields.

Id is unique: no two Prospect records may share the same value, and a save that would duplicate one is rejected. Party must be filled in before the record can be saved.

Every Prospect points at Party. Choose the linked record from the lookup on those fields rather than typing an identifier.

Every save starts as a Draft. The business rules and workflows attached to Prospect then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Prospect with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4a0931b7-9f89-592d-9216-0b70d128b64c', 'bus_prospect', 'Prospect', 'A potential customer or account that has been identified but is not yet qualified as a Lead or established as a Customer. Provide canonical implementation-neutral semantics for Prospect across enterprise applications. A potential customer or account that has been identified but is not yet qualified as a Lead or established as a Customer. Used in CRM, sales, fulfillment, logistics, reporting, integration, or audit processes where this concept applies. Connects to canonical parties, commercial transactions, logistics execution, and downstream evidence without replacing their authoritative records. Created and progressed through governed business workflow; completed history is retained and corrections are explicit. Commercial management, fulfillment, logistics execution, reconciliation, reporting, and audit. Enterprise sales and supply-chain operations.', 'A', FALSE, FALSE, FALSE, TRUE, '72f2359d-70d2-5bc0-a91a-7609935a3571', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
