-- --------------------------------------------------------------------------
-- Customer Return (bus_customer_return)
-- --------------------------------------------------------------------------
INSERT INTO sys_window (sys_window_id, name, description, help, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d531139a-3660-5f8e-8d4c-0eaba7bc70d9', 'Customer Return', 'Maintain Customer Return records', 'Create, find and maintain Customer Return records. The list shows every Customer Return you have access to — select a row to open it, or use New to add one. Each row is a single Customer Return, described by 8 fields.

Id and Return Number are unique: no two Customer Return records may share the same value, and a save that would duplicate one is rejected. Return Number, Status, Return Date and Customer must be filled in before the record can be saved.

Every Customer Return points at Customer and Sales Order. Choose the linked record from the lookup on those fields rather than typing an identifier. Customer Return Line refers back to Customer Return, so what you change here can affect that record.

Every save starts as a Draft. The business rules and workflows attached to Customer Return then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Customer Return with no rules or workflows attached is marked Final immediately.', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('6fa63e42-4a2e-5d1b-9210-2bc575f00326', 'bus_customer_return', 'Customer Return', 'Coordinates the controlled reversal of a customer fulfillment while preserving original commercial, inventory and financial history. A return is a new business event caused by a prior sale; it is not deletion or mutation of the original sale. A CreditNote is the separate financial consequence. Customer service, reverse logistics, warehouse receiving, quality, inventory, credit processing, accounts receivable and audit. SalesOrder/SalesOrderLine identify original demand, Shipment identifies prior logistics, Invoice identifies financial claims, CustomerReturnLine identifies returned quantities, disposition determines inventory consequences, and CreditNote records approved financial adjustment. Return request → authorization → return shipment → receipt → inspection → disposition → inventory movement if applicable → credit eligibility → CreditNote approval/posting if applicable → completion. Original sale and invoice remain unchanged. Draft → authorized → in transit → received → inspection → dispositioned → completed, with cancellation and exception paths. Authorization validates prior fulfillment; receipt creates no unrestricted inventory by itself; disposition drives inventory; approved financial adjustment creates CreditNote and accounting/application effects without mutating original documents. A customer returns 5 of 20 shipped units. Three are restocked, one quarantined and one scrapped. Inventory receives only the three restock units; an approved CreditNote handles the financial adjustment for the eligible credited amount.', 'A', FALSE, FALSE, FALSE, TRUE, 'd531139a-3660-5f8e-8d4c-0eaba7bc70d9', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_tab (sys_tab_id, sys_window_id, sys_table_id, name, help, tab_level, seq_no, is_single_row, has_tree, is_info_tab, is_translation_tab, is_read_only, is_insert_record, is_advanced_tab, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('2adb9a0a-2d2d-5b30-a917-7d5c49d6a1dd', 'd531139a-3660-5f8e-8d4c-0eaba7bc70d9', '6fa63e42-4a2e-5d1b-9210-2bc575f00326', 'Customer Return', 'Shows one Customer Return at a time. Fields are grouped: General carries the identifying fields and Details carries the rest. 4 fields marked with a red asterisk (*) must have a value before Save will accept the record. Customer and Sales Order are lookups — search the linked records instead of entering an identifier by hand. Any field showing a ? beside its label has help of its own; click it for the rules that apply there.', 0, 10, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
