VALUES ('1d043402-cd20-5056-8255-8a71a371edcd', '6fa63e42-4a2e-5d1b-9210-2bc575f00326', 'return_number', 'Return Number', 'Business-facing customer return reference. Identifies the return for customer service, warehouse and finance operations. Used in return authorization, transport, receiving, inspection, credit and audit. Distinct from customerReturnId, Shipment and CreditNote numbers. Provides operational reference throughout the return lifecycle. Required for operational traceability.', 10, 100, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, TRUE, FALSE, FALSE, TRUE, TRUE, 20, 'U', TRUE, 'system', 'system', NOW(), NOW())
