INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('8954e75a-c5b8-502d-9113-dca050e56d54', '299f2906-5bf5-5416-941b-3f49598b9107', 'unit_price', 'Unit Price', 'Transaction-time quoted price per unit, including its currency. Used for quotation valuation and, when accepted, as source evidence for downstream SalesOrder pricing. Must be interpreted with the quotation currency and UnitOfMeasure. Price determination may source a current price rule, but the accepted quotation retains this effective price. Required for a financially valued quotation line.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e02d067e-8f0f-5070-bc62-2ee864cd9deb', '299f2906-5bf5-5416-941b-3f49598b9107', 'amount', 'Amount', 'Calculated gross commercial value of the quotation line before any separately represented adjustments. Supports quotation totals and conversion validation. Currency must match unitPrice and the quotation currency under the quotation''s pricing policy. Provides a reproducible quoted amount. Required for a financially valued quotation line.', 12, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('be1cea00-b17b-5698-b366-b80defef241d', '299f2906-5bf5-5416-941b-3f49598b9107', 'discount_amount', 'Discount Amount', 'Transaction-time discount amount granted on the quoted line. Preserves the commercial concession used to derive the net amount. Must use the quotation currency. Prevents later DiscountRule changes from rewriting an accepted quotation. Optional when no discount applies.', 12, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 60, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('445360bb-6046-5b1e-9944-fc9132a07438', '299f2906-5bf5-5416-941b-3f49598b9107', 'price_source', 'Price Source', 'Records the business source used to determine the quoted price. Supports audit, margin analysis, pricing explanation, and downstream conversion. Source metadata does not replace the transaction-time unitPrice. Explains why the quoted price was selected. Optional when the quotation does not require source attribution.', 1035, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 70, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('a86c38f2-cfea-521a-9a9f-8e2ad272ef49', '299f2906-5bf5-5416-941b-3f49598b9107', 'price_determined_at', 'Price Determined At', 'Timestamp at which the quoted price was determined. Supports effective-dated pricing audit and reproducibility. Distinct from quotation creation time when pricing is recalculated or manually overridden. Provides temporal evidence for price determination. Optional only where the quotation process does not capture determination timing.', 16, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 80, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
