INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('73807924-31e7-57ea-bfbf-30b747dc0e03', '381729f6-0207-554e-9a89-1d273a0a9c22', '8954e75a-c5b8-502d-9113-dca050e56d54', 'ae488805-a94b-563a-a32d-bcadd652e9ac', 'Unit Price', 'Transaction-time quoted price per unit, including its currency. Used for quotation valuation and, when accepted, as source evidence for downstream SalesOrder pricing. Must be interpreted with the quotation currency and UnitOfMeasure. Price determination may source a current price rule, but the accepted quotation retains this effective price. Required for a financially valued quotation line. Required — the record cannot be saved while this is empty.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('4e454e2b-5337-5ec5-94cb-c41f2c18830b', '381729f6-0207-554e-9a89-1d273a0a9c22', 'e02d067e-8f0f-5070-bc62-2ee864cd9deb', 'ae488805-a94b-563a-a32d-bcadd652e9ac', 'Amount', 'Calculated gross commercial value of the quotation line before any separately represented adjustments. Supports quotation totals and conversion validation. Currency must match unitPrice and the quotation currency under the quotation''s pricing policy. Provides a reproducible quoted amount. Required for a financially valued quotation line. Required — the record cannot be saved while this is empty.', 50, 50, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ad4f717f-9a41-568b-993d-d8f955589622', '381729f6-0207-554e-9a89-1d273a0a9c22', 'be1cea00-b17b-5698-b366-b80defef241d', 'ae488805-a94b-563a-a32d-bcadd652e9ac', 'Discount Amount', 'Transaction-time discount amount granted on the quoted line. Preserves the commercial concession used to derive the net amount. Must use the quotation currency. Prevents later DiscountRule changes from rewriting an accepted quotation. Optional when no discount applies.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
