INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('abcbd295-384a-553e-af82-2fae675fb4ee', '381729f6-0207-554e-9a89-1d273a0a9c22', '445360bb-6046-5b1e-9944-fc9132a07438', 'ae488805-a94b-563a-a32d-bcadd652e9ac', 'Price Source', 'Records the business source used to determine the quoted price. Supports audit, margin analysis, pricing explanation, and downstream conversion. Source metadata does not replace the transaction-time unitPrice. Explains why the quoted price was selected. Optional when the quotation does not require source attribution.', 70, 70, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ba5927f0-fe54-5568-8c26-a6f339d53059', '381729f6-0207-554e-9a89-1d273a0a9c22', 'a86c38f2-cfea-521a-9a9f-8e2ad272ef49', 'ae488805-a94b-563a-a32d-bcadd652e9ac', 'Price Determined At', 'Timestamp at which the quoted price was determined. Supports effective-dated pricing audit and reproducibility. Distinct from quotation creation time when pricing is recalculated or manually overridden. Provides temporal evidence for price determination. Optional only where the quotation process does not capture determination timing.', 80, 80, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
