INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('1358a288-ac29-5e04-9172-7bf66cecd135', '231c84f1-2c33-545d-b097-1dc68734ed6c', 'f4f12603-014e-5393-ad3b-8f6588ed6bab', '0b0c39c8-2eea-545a-b2a9-d9593d5a7b5a', 'Id', 'Immutable identity of the customer return line. Identifies one returned-item detail independently of the parent return, source order line, inventory movement or credit note. Used for quantity reconciliation, inventory posting, credit calculation and audit. Stable bridge identity across reverse-fulfillment and financial workflows. Carries source quantity through receipt, disposition and downstream credit processing. Required for traceability. Must be unique: a save is rejected if another Customer Return Line already uses this value.', 10, 10, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('25479d99-2a24-53b0-b2cf-5568e04f9c1e', '231c84f1-2c33-545d-b097-1dc68734ed6c', 'f6627544-b86d-5fdd-a6b7-12a5b00fe37f', '0b0c39c8-2eea-545a-b2a9-d9593d5a7b5a', 'Line Number', 'Sequence number of the line within the CustomerReturn. Identifies the line for operational documents and reconciliation. Used in return documents, receiving and audit. Unique within the parent return and independent of SalesOrderLine or InvoiceLine numbering. Supports deterministic return reconstruction. Required for line identification. Required — the record cannot be saved while this is empty.', 20, 20, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('86fa8245-8b9f-5520-a89d-af76abffe513', '231c84f1-2c33-545d-b097-1dc68734ed6c', 'af9845f4-cb95-53bd-9517-236fe8dc5634', '0b0c39c8-2eea-545a-b2a9-d9593d5a7b5a', 'Quantity Returned', 'Quantity physically or contractually returned for this line. Establishes the quantity subject to inspection and disposition. Used for return validation, inventory and financial eligibility. Must be supported by prior fulfillment evidence and cannot automatically become inventory or credit. Feeds disposition quantities and potential credit calculation. Required because a return line must represent a quantity or equivalent source value. Required — the record cannot be saved while this is empty.', 30, 30, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e4d71fa3-f4b9-5090-a941-263026f1a5d1', '231c84f1-2c33-545d-b097-1dc68734ed6c', '020f40f6-c136-5561-8783-7d0e9f30a9c2', 'ae488805-a94b-563a-a32d-bcadd652e9ac', 'Quantity Restocked', 'Quantity accepted for unrestricted restocking. Represents returned goods approved to re-enter unrestricted inventory. Drives positive InventoryMovement posting. Must be a component of quantityReturned and is the only disposition component eligible for unrestricted stock. Creates the inventory consequence after disposition approval. Required as zero when none is restocked. Required — the record cannot be saved while this is empty.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('cfd1fad5-829f-5403-bcf1-87dd69726ba8', '231c84f1-2c33-545d-b097-1dc68734ed6c', '98ff4f9a-2959-5f3b-a790-980781eee1b7', 'ae488805-a94b-563a-a32d-bcadd652e9ac', 'Quantity Quarantined', 'Quantity placed into restricted or quarantine inventory. Represents returned goods requiring further inspection or controlled handling. Supports quality and restricted inventory workflows. Does not increase unrestricted available inventory. Drives restricted disposition workflow. Required as zero when none is quarantined. Required — the record cannot be saved while this is empty.', 50, 50, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('73aa3608-e90d-51c1-a868-3c1bc19ccdde', '231c84f1-2c33-545d-b097-1dc68734ed6c', 'e4854ce6-8787-57ea-8890-d48664732368', 'ae488805-a94b-563a-a32d-bcadd652e9ac', 'Quantity To Repair', 'Quantity routed to repair or refurbishment. Represents goods that require a repair process before any future stock disposition. Supports maintenance/repair work orders and inventory control. Does not directly create unrestricted stock. Drives repair workflow and later disposition. Required as zero when none is routed to repair. Required — the record cannot be saved while this is empty.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d5e476a8-330b-5106-a80f-57ef81e43917', '231c84f1-2c33-545d-b097-1dc68734ed6c', 'fdab647a-ef72-5715-a32e-985251315514', 'ae488805-a94b-563a-a32d-bcadd652e9ac', 'Quantity Scrapped', 'Quantity approved for scrap or disposal. Represents returned goods that will not return to saleable inventory. Supports disposal, environmental controls and inventory adjustment. Does not increase unrestricted available inventory. Drives authorized disposal and inventory adjustment. Required as zero when none is scrapped. Required — the record cannot be saved while this is empty.', 70, 70, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e4b26179-d334-53b6-9fdc-afadea7dbd1d', '231c84f1-2c33-545d-b097-1dc68734ed6c', '98470b43-6927-56f6-829a-554e3de5bfad', 'ae488805-a94b-563a-a32d-bcadd652e9ac', 'Disposition', 'Physical disposition assigned after inspection of returned goods. Determines what operational path the returned quantity follows. Drives inventory, quality, repair and disposal processing. Distinct from return reason and financial credit reason. Determines authoritative InventoryMovement or downstream workflow. Required to prevent ambiguous physical treatment. Required — the record cannot be saved while this is empty.', 80, 80, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b54199c1-f392-581a-a2ea-844677f6069d', '231c84f1-2c33-545d-b097-1dc68734ed6c', '88146867-f07d-505e-92bf-67560b59bada', 'ae488805-a94b-563a-a32d-bcadd652e9ac', 'Approved Credit Amount', 'Maximum financial credit approved for this return line under applicable policy. Provides the financial eligibility basis consumed by CreditNoteLine; it is not itself a posted credit. Supports customer credit calculation, approval and audit. Must reconcile with original InvoiceLine pricing/tax evidence and must not mutate the invoice. Limits return-based CreditNoteLine credit unless a separate authorized adjustment applies. Optional when the return has no financial credit consequence.', 90, 90, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('2eefc6ff-773c-5a86-80c2-6b81dd6f96e2', '231c84f1-2c33-545d-b097-1dc68734ed6c', '27d8c224-b2da-5483-9b76-6c51a041decd', 'ae488805-a94b-563a-a32d-bcadd652e9ac', 'Customer Return', 'Parent return containing this returned quantity detail. Establishes the authorization and lifecycle context. Supports return processing and completion. Parent lifecycle coordinates this line''s processing. Required — the record cannot be saved while this is empty.', 100, 100, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
